#include <cstdio>
#include <vector>
#include <unordered_map>
#include <queue>
using namespace std;
int nums[500010];

class DualHeap {
private:
    priority_queue<int> low;
    priority_queue<int, vector<int>, greater<int>> high;
    unordered_map<int, int> removed;
    int lowCount = 0;
    int highCount = 0;

    template<typename T>
    void clean(T& heap) {
        while (!heap.empty() && removed[heap.top()] > 0) {
            removed[heap.top()]--;
            heap.pop();
        }
    }

    void balance() {
        if (lowCount > highCount + 1) {
            lowCount -= 1;
            highCount += 1;
            high.push(low.top());
            low.pop();
            clean(low);
        } else if (lowCount < highCount) {
            lowCount += 1;
            highCount -= 1;
            low.push(high.top());
            high.pop();
            clean(high);
        }
    }

public:
    void insert(int num) {
        if (low.empty() || num <= low.top()) {
            lowCount += 1;
            low.push(num);
        } else {
            highCount += 1;
            high.push(num);
        }
        balance();
    }

    void erase(int num) {
        removed[num]++;
        if (!low.empty() && num <= low.top()) {
            lowCount -= 1;
            clean(low);
        } else {
            highCount -= 1;
            clean(high);
        }
        balance();
    }

    int getMid() {
        return low.top();
    }

    int size() {
        return lowCount + highCount;
    }
};

int main() {
    int n, k;
    scanf("%d%d", &n, &k);

    DualHeap dualHeap;
    unordered_map<int, int> counter;
    for (int i = 0; i < k; i++) {
        scanf("%d", &nums[i]);
        counter[nums[i]]++;
        if (counter[nums[i]] == 1) {
            dualHeap.insert(nums[i]);
        } else if (counter[nums[i]] == 2) {
            dualHeap.erase(nums[i]);
        }
    }
    if (dualHeap.size() == 0) {
        printf("-1\n");
    } else {
        printf("%d\n", dualHeap.getMid());
    }
    for (int i = k; i < n; i++) {
		scanf("%d", &nums[i]);
        counter[nums[i - k]]--;
        if (counter[nums[i - k]] == 1) {
            dualHeap.insert(nums[i - k]);
        } else if (counter[nums[i - k]] == 0) {
            dualHeap.erase(nums[i - k]);
        }

        counter[nums[i]]++;
        if (counter[nums[i]] == 1) {
            dualHeap.insert(nums[i]);
        } else if (counter[nums[i]] == 2) {
            dualHeap.erase(nums[i]);
        }

        if (dualHeap.size() == 0) {
            printf("-1\n");
        } else {
            printf("%d\n", dualHeap.getMid());
        }
    }

    return 0;
}
